classDiagram
    class Calculator {
        +calculate(expression: str) -> str
        -parse(expression: str) -> list
        -evaluate(tokens: list) -> Decimal
        -format_result(result: Decimal) -> str
    }
    class Tokenizer {
        +tokenize(expression: str) -> list
        -is_operator(char: str) -> bool
        -is_digit(char: str) -> bool
    }
    class Parser {
        +parse(tokens: list) -> ASTNode
        -parse_expression() -> ASTNode
        -parse_term() -> ASTNode
        -parse_factor() -> ASTNode
    }
    class ASTNode {
        <<abstract>>
        +evaluate() -> Decimal
    }
    class NumberNode {
        -value: Decimal
        +evaluate() -> Decimal
    }
    class BinaryOpNode {
        -left: ASTNode
        -right: ASTNode
        -operator: str
        +evaluate() -> Decimal
    }
    class Evaluator {
        +evaluate(node: ASTNode) -> Decimal
    }
    class Formatter {
        +format(value: Decimal) -> str
    }
    Calculator --> Tokenizer
    Calculator --> Parser
    Calculator --> Evaluator
    Calculator --> Formatter
    Parser --> ASTNode
    ASTNode <|-- NumberNode
    ASTNode <|-- BinaryOpNode
    Evaluator --> ASTNode
